code.cpp:
class Solution {
public:
    int maxRepOpt1(string text) {
        int n = text.size();
        int ans = 0;
        for (char c = 'a'; c <= 'z'; ++c) {
            int total_c = 0;
            for (int i = 0; i < n; ++i) {
                if (text[i] == c) total_c++;
            }

            int left = 0;
            int non_c_count = 0;
            for (int right = 0; right < n; ++right) {
                if (text[right] != c) {
                    non_c_count++;
                }
                while (non_c_count > 1) {
                    if (text[left] != c) {
                        non_c_count--;
                    }
                    left++;
                }
                int window_len = right - left + 1;
                if (non_c_count == 0) {
                    ans = max(ans, min(total_c, window_len + 1));
                } else {
                    ans = max(ans, min(total_c, window_len));
                }
            }
        }
        return ans;
    }
};
